  angle=function(x,y) return 0.03 + 0.05*math.sin(x/200) end, coverage=3, fill=true, clip=true, tool="filbert 16", length={80,200}, pressure={0.4,0.7}})
blend(skyM:shrink(4), {angle=0.03})

