skyD = pile{{"lead white",4},{"cerulean blue",1.0},{"cobalt blue",0.4},{"ultramarine ash",0.4}, name="skyD"}
local top = skyM * mask(function(x,y) return clamp(1 - y/150 - (x-400)/3000, 0, 1) end)
work(top, {hand="broad", pile=skyD, angle=0.04, coverage=2, fill=true, clip=skyM, tool="filbert 16", length={100,220}, pressure={0.35,0.6}, threshold=0.25})
blend(skyM:shrink(4) * rect(0,0,1000,200), {angle=0.03})
-- soft cloud strands
cloud = pile{{"lead white",6},{"Naples yellow",0.4},{"cobalt violet",0.08}, name="cloud"}
cb = brush{kind="filbert", width=10, stiffness=0.3}
cb:load(cloud, 0.5)
local strands = {{{560,150},{700,140},{860,146},{1000,138}}, {{640,190},{760,184},{900,190}}, {{700,95},{820,88},{960,92}}, {{480,120},{560,116},{620,118}}}
for _,s in ipairs(strands) do cb:stroke(s, {pressure={0.35,0.15}, ramps={0.2,0.4}, clip=skyM}); cb:load(cloud,0.4) end
blend(skyM:shrink(4) * rect(450,70,550,140), {angle=0.0})

